-- Phase 6: controlled invoicing, receipts, refunds, expenses, journals and commissions.
create sequence public.finance_quote_seq;create sequence public.finance_invoice_seq;create sequence public.finance_receipt_seq;create sequence public.finance_voucher_seq;create sequence public.commission_agreement_seq;
create table public.finance_quotations(id uuid primary key default gen_random_uuid(),quotation_no text not null unique,student_id uuid not null references public.students(id),course text not null,service_category text not null,income_account_code text not null,subtotal numeric(14,2) not null check(subtotal>=0),discount numeric(14,2) not null default 0 check(discount>=0 and discount<=subtotal),grand_total numeric(14,2) generated always as(subtotal-discount)stored,valid_until date not null,status text not null default'DRAFT'check(status in('DRAFT','SENT','ACCEPTED','REJECTED','EXPIRED','CONVERTED')),created_by uuid not null references public.staff_profiles(id),created_at timestamptz not null default now());
create table public.finance_invoices(id uuid primary key default gen_random_uuid(),invoice_no text not null unique,quotation_id uuid references public.finance_quotations(id),student_id uuid not null references public.students(id),course text not null,service_category text not null,income_account_code text not null,subtotal numeric(14,2) not null check(subtotal>=0),discount numeric(14,2) not null default 0 check(discount>=0 and discount<=subtotal),grand_total numeric(14,2) generated always as(subtotal-discount)stored,status text not null check(status in('PAID','PENDING','PARTIAL','CANCELLED','REFUNDED')),created_by uuid not null references public.staff_profiles(id),created_at timestamptz not null default now());
create table public.finance_receipts(id uuid primary key default gen_random_uuid(),receipt_no text not null unique,invoice_id uuid not null references public.finance_invoices(id),amount numeric(14,2) not null check(amount>0),payment_method text not null,asset_account_code text not null,received_by uuid not null references public.staff_profiles(id),received_at timestamptz not null default now());
create table public.finance_journals(id uuid primary key default gen_random_uuid(),voucher_no text not null unique,reference_no text not null,description text not null,status text not null default'POSTED'check(status in('DRAFT','PENDING_APPROVAL','POSTED','REVERSED')),prepared_by uuid not null references public.staff_profiles(id),approved_by uuid references public.staff_profiles(id),posted_at timestamptz,created_at timestamptz not null default now());
create table public.finance_journal_lines(id uuid primary key default gen_random_uuid(),journal_id uuid not null references public.finance_journals(id)on delete cascade,account_code text not null,debit numeric(14,2)not null default 0 check(debit>=0),credit numeric(14,2)not null default 0 check(credit>=0),check((debit>0 and credit=0)or(credit>0 and debit=0)));
create table public.finance_refunds(id uuid primary key default gen_random_uuid(),receipt_id uuid not null references public.finance_receipts(id),amount numeric(14,2)not null check(amount>0),reason text not null,status text not null default'PENDING_APPROVAL'check(status in('PENDING_APPROVAL','APPROVED','REJECTED','PAID')),requested_by uuid not null references public.staff_profiles(id),approved_by uuid references public.staff_profiles(id),created_at timestamptz not null default now());
create table public.finance_expenses(id uuid primary key default gen_random_uuid(),expense_no text not null unique,description text not null,expense_account_code text not null,amount numeric(14,2)not null check(amount>0),payment_account_code text not null,status text not null default'PENDING_APPROVAL'check(status in('PENDING_APPROVAL','APPROVED','REJECTED','PAID')),requested_by uuid not null references public.staff_profiles(id),approved_by uuid references public.staff_profiles(id),expense_date date not null,created_at timestamptz not null default now());
create table public.university_commissions(id uuid primary key default gen_random_uuid(),agreement_no text not null unique,student_id uuid not null references public.students(id),university_name text not null,country text not null,commission_type text not null check(commission_type in('Percentage','Fixed Amount')),rate_pct numeric(6,2)not null,tuition_fee_npr numeric(14,2)not null,commission_due_npr numeric(14,2)not null,received_npr numeric(14,2)not null default 0,due_date date not null,status text not null default'PENDING'check(status in('PENDING','RECEIVED','OVERDUE')),created_by uuid not null references public.staff_profiles(id),created_at timestamptz not null default now());
create or replace function public.enforce_balanced_journal()returns trigger language plpgsql as $$declare d numeric;c numeric;begin select coalesce(sum(debit),0),coalesce(sum(credit),0)into d,c from finance_journal_lines where journal_id=new.id;if d<>c or d=0 then raise exception'Journal is not balanced';end if;return new;end$$;create constraint trigger finance_journal_balanced after insert or update of status on public.finance_journals deferrable initially deferred for each row when(new.status='POSTED')execute function public.enforce_balanced_journal();
insert into public.permissions(role,permission_name,enabled)select role,permission_name,true from(values('ADMIN'::public.staff_role),('DIRECTOR'),('ACCOUNTANT'),('FINANCE'))r(role)cross join(values('finance.view'),('finance.create'),('finance.approve'))p(permission_name)on conflict(role,permission_name)do update set enabled=excluded.enabled;
do $$declare t text;begin foreach t in array array['finance_quotations','finance_invoices','finance_receipts','finance_journals','finance_journal_lines','finance_refunds','finance_expenses','university_commissions']loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I_read on public.%I for select to authenticated using(public.has_permission(''finance.view''))',t,t);end loop;end$$;
create or replace function public.issue_student_invoice(payload jsonb)returns jsonb language plpgsql security definer set search_path=public as $$declare sid uuid;iid uuid;rid uuid;jid uuid;ino text;rno text;vno text;asset text;total numeric;received numeric;begin if not public.has_permission('finance.create')then raise exception'Insufficient permission';end if;select id into sid from students where student_code=payload->>'student_code';if sid is null then raise exception'Student not found';end if;total:=(payload->>'subtotal')::numeric-(payload->>'discount')::numeric;received:=(payload->>'amount_received')::numeric;if received>total then raise exception'Receipt cannot exceed invoice total';end if;ino:='INV-'||to_char(now(),'YYYY')||'-'||lpad(nextval('finance_invoice_seq')::text,6,'0');insert into finance_invoices(invoice_no,student_id,course,service_category,income_account_code,subtotal,discount,status,created_by)values(ino,sid,payload->>'course',payload->>'service_category',payload->>'income_account_code',(payload->>'subtotal')::numeric,(payload->>'discount')::numeric,case when received=total then'PAID'when received>0 then'PARTIAL'else'PENDING'end,auth.uid())returning id into iid;if received>0 then asset:=case when payload->>'payment_method'ilike any(array['%eSewa%','%Khalti%'])then'1115'when payload->>'payment_method'ilike any(array['%Bank%','%ConnectIPS%'])then'1113'else'1111'end;rno:='REC-'||to_char(now(),'YYYY')||'-'||lpad(nextval('finance_receipt_seq')::text,6,'0');insert into finance_receipts(receipt_no,invoice_id,amount,payment_method,asset_account_code,received_by)values(rno,iid,received,payload->>'payment_method',asset,auth.uid())returning id into rid;vno:='JV-'||to_char(now(),'YYYY')||'-'||lpad(nextval('finance_voucher_seq')::text,6,'0');insert into finance_journals(voucher_no,reference_no,description,status,prepared_by,approved_by,posted_at)values(vno,ino,'Student fee receipt','DRAFT',auth.uid(),auth.uid(),now())returning id into jid;insert into finance_journal_lines(journal_id,account_code,debit)values(jid,asset,received);insert into finance_journal_lines(journal_id,account_code,credit)values(jid,payload->>'income_account_code',received);update finance_journals set status='POSTED'where id=jid;end if;return jsonb_build_object('id',iid,'invoice_no',ino,'receipt_no',rno);end$$;
create or replace function public.create_commission(payload jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare sid uuid;cid uuid;due numeric;ano text;begin if not public.has_permission('finance.create')then raise exception'Insufficient permission';end if;select id into sid from students where student_code=payload->>'student_code';if sid is null then raise exception'Student not found';end if;due:=case when payload->>'commission_type'='Percentage'then(payload->>'tuition_fee_npr')::numeric*(payload->>'rate_pct')::numeric/100 else(payload->>'tuition_fee_npr')::numeric end;ano:='AGR-'||to_char(now(),'YYYY')||'-'||lpad(nextval('commission_agreement_seq')::text,5,'0');insert into university_commissions(agreement_no,student_id,university_name,country,commission_type,rate_pct,tuition_fee_npr,commission_due_npr,due_date,created_by)values(ano,sid,payload->>'university_name',payload->>'country',payload->>'commission_type',(payload->>'rate_pct')::numeric,(payload->>'tuition_fee_npr')::numeric,due,(payload->>'due_date')::date,auth.uid())returning id into cid;return cid;end$$;
revoke all on function public.issue_student_invoice(jsonb),public.create_commission(jsonb)from public;grant execute on function public.issue_student_invoice(jsonb),public.create_commission(jsonb)to authenticated;
